export const acceso = {
  cuentaOrigen: "111111111111",
  cuentaDestino: "999999999999",
  rol: {
    arn: "arn:aws:iam::999999999999:role/ActualizarDatos",
    politicaConfianza: { principales: ["111111111111"] },
    politicaPermisos: [
      { efecto: "Allow", acciones: ["s3:GetObject", "s3:PutObject"], recurso: "arn:aws:s3:::bucket-compartido/*" },
    ],
  },
  desarrolladores: {
    politicas: [
      { efecto: "Allow", acciones: ["s3:ListAllMyBuckets"], recurso: "*" },
      { efecto: "Allow", acciones: ["sts:AssumeRole"], recurso: "arn:aws:iam::999999999999:role/ActualizarDatos" },
    ],
  },
};

spec.code:
for (const p of acceso.desarrolladores.politicas) {
  if (p.acciones.includes("sts:AssumeRole")) {
    assert.ok(!p.recurso.includes("*"), "el recurso de sts:AssumeRole no debe llevar comodines");
  }
}

assert.deepStrictEqual(acceso.rol.politicaConfianza.principales, ["111111111111"]);
assert.ok(acceso.rol.arn.includes(acceso.cuentaDestino), "el rol vive en la cuenta de destino");
assert.strictEqual(acceso.rol.politicaPermisos.length, 1);
assert.deepStrictEqual(acceso.rol.politicaPermisos[0].acciones, ["s3:GetObject", "s3:PutObject"]);

