export const servidor = {
  instancia: { id: "i-app", perfilInstancia: "perfil-app", credencialesFijas: null },
  perfilesInstancia: [
    { nombre: "perfil-app", roles: ["rol-lectura-s3"] },
  ],
  roles: [
    {
      nombre: "rol-lectura-s3",
      politicaConfianza: { principales: ["servicio:ec2"] },
      politicaPermisos: [{ efecto: "Allow", acciones: ["s3:GetObject"], recurso: "arn:aws:s3:::bucket-datos/*" }],
    },
    {
      nombre: "rol-escritura-s3",
      politicaConfianza: { principales: ["servicio:ec2"] },
      politicaPermisos: [{ efecto: "Allow", acciones: ["s3:PutObject"], recurso: "arn:aws:s3:::bucket-datos/*" }],
    },
  ],
};

spec.code:
const perfil = servidor.perfilesInstancia.find((p) => p.nombre === servidor.instancia.perfilInstancia);
assert.ok(perfil, "la instancia debe usar un perfil que exista");
assert.strictEqual(perfil.roles.length, 1, "un perfil de instancia solo puede contener un rol");

const perfil = servidor.perfilesInstancia.find((p) => p.nombre === servidor.instancia.perfilInstancia);
const rol = servidor.roles.find((r) => r.nombre === perfil.roles[0]);
assert.ok(rol, "el rol del perfil debe existir");
assert.ok(rol.politicaConfianza.principales.includes("servicio:ec2"), "la confianza debe nombrar a Amazon EC2");

const perfil = servidor.perfilesInstancia.find((p) => p.nombre === servidor.instancia.perfilInstancia);
assert.deepStrictEqual(perfil.roles, ["rol-lectura-s3"]);
const lectura = servidor.roles.find((r) => r.nombre === "rol-lectura-s3");
assert.deepStrictEqual(lectura.politicaPermisos, [{ efecto: "Allow", acciones: ["s3:GetObject"], recurso: "arn:aws:s3:::bucket-datos/*" }]);
